#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-load-mailboxes-from-a-csv-file. Do not edit.
set -e
cd "$(dirname "$0")"
cat > make-mailboxes.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Writes mailboxes.csv: forty test mailboxes, tester01 to tester40. The last ten log in over IMAP
# only; the rest have an empty protocols field, which means every mail protocol.
echo "address,password,protocols" > mailboxes.csv
i=1
while [ "$i" -le 40 ]; do
  n=$(printf '%02d' "$i")
  if [ "$i" -le 30 ]; then protocols=""; else protocols="imap"; fi
  echo "tester$n@example.com,pass$n,$protocols" >> mailboxes.csv
  i=$((i + 1))
done
EOF
cat > quoted.csv <<'EOF'
address,password,protocols
ops@example.com,"s3cret,too",imap
EOF
cat > outside.csv <<'EOF'
address,password,protocols
ops@example.com,"s3cret,too",imap

carol@elsewhere.org,carolpass,
EOF
cat > again.csv <<'EOF'
address,password
tester05@example.com,another
EOF
cat > columns.csv <<'EOF'
address,pass
ann@example.com,annpass
EOF
cat > note.eml <<'EOF'
From: tester01@example.com
To: tester02@example.com
Subject: Build 812 passed

All 40 suites passed.
EOF
sh make-mailboxes.sh
surl -v --log-file surl.log --mail-domain example.com --mailbox-file mailboxes.csv smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ pop3://127.0.0.1:8082/ &
sleep 1
curl -sS --crlf -u tester01@example.com:pass01 --mail-from tester01@example.com --mail-rcpt tester02@example.com -T note.eml smtp://127.0.0.1:8080/ci.example.com --next -sS --retry 10 --retry-all-errors --retry-delay 1 -u tester02@example.com:pass02 "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(SUBJECT)"
kill $(jobs -p)
